@@ -1,3 +1,51 @@
+const UNIT_MS = {
+  d: 24 * 60 * 60 * 1000,
+  h: 60 * 60 * 1000,
+  m: 60 * 1000,
+  s: 1000,
+  ms: 1,
+};
+
+const TOKEN_RE = /(\d+)\s*(ms|d|h|m|s)/g;
+
 export function parseDuration(value) {
-  return Number(value);
+  if (typeof value !== "string" || value.trim() === "") {
+    throw new Error("Invalid duration: input must be a non-empty string");
+  }
+
+  const trimmed = value.trim();
+  const seen = new Set();
+  let totalMs = 0;
+  let matchedLength = 0;
+  let lastIndex = 0;
+
+  TOKEN_RE.lastIndex = 0;
+  let match;
+  while ((match = TOKEN_RE.exec(trimmed)) !== null) {
+    if (match.index !== lastIndex) {
+      throw new Error(`Invalid duration: unexpected text in "${trimmed}"`);
+    }
+
+    const [full, amount, unit] = match;
+    if (seen.has(unit)) {
+      throw new Error(`Invalid duration: duplicate unit "${unit}" in "${trimmed}"`);
+    }
+    seen.add(unit);
+
+    totalMs += Number(amount) * UNIT_MS[unit];
+    matchedLength += full.length;
+    lastIndex = match.index + full.length;
+
+    // skip whitespace between tokens
+    while (lastIndex < trimmed.length && /\s/.test(trimmed[lastIndex])) {
+      lastIndex++;
+    }
+    TOKEN_RE.lastIndex = lastIndex;
+  }
+
+  if (lastIndex !== trimmed.length || seen.size === 0) {
+    throw new Error(`Invalid duration: could not fully parse "${trimmed}"`);
+  }
+
+  return totalMs;
 }
